//! The native engine against OpenJDK 27's own answers.
//!
//! `oracle_cases.rs` is generated by `tools/java_regex_oracle.py` from a run
//! of the real `java.util.regex` (`--emit-rust`); nothing in it is derived
//! from this module. Every answer the engine gives must equal Java's; a
//! pattern or call it counts instead ([`Unsupported`]) is allowed, but never
//! for a pattern Java rejects, which the engine must not accept.

use super::{Regex, Thrown, Unsupported, matches, quote, quote_replacement, string_split};

// Generated data: one case per line group, kept as the script writes it.
#[rustfmt::skip]
#[path = "oracle_cases.rs"]
mod oracle_cases;

/// One pattern and Java's answers for it.
pub(super) struct Case {
    pub(super) pattern: &'static str,
    pub(super) flags: i32,
    /// `Pattern.compile`'s exception, `"!class: message"`.
    pub(super) compile_error: Option<&'static str>,
    pub(super) groups: usize,
    pub(super) inputs: &'static [Input],
}

/// Java's answers on one input. Strings starting with `!` are exceptions.
pub(super) struct Input {
    pub(super) input: &'static str,
    pub(super) matches: bool,
    pub(super) looking_at: bool,
    /// Every `find()`: `start(g), end(g)` for each group, `-1` unset.
    pub(super) find: &'static [&'static [i64]],
    /// `(replacement, replaceAll, replaceFirst)`.
    pub(super) replace: &'static [(&'static str, &'static str, &'static str)],
    /// `Pattern.split` at limits 0, -1, 1, 2, 3.
    pub(super) split: &'static [Result<&'static [&'static str], &'static str>],
    /// `String.split` at limits 0 and 2 (flags 0 only).
    pub(super) string_split: Option<&'static [Result<&'static [&'static str], &'static str>]>,
}

/// A recorded split (the generated table's constructor).
pub(super) const fn ok(
    parts: &'static [&'static str],
) -> Result<&'static [&'static str], &'static str> {
    Ok(parts)
}

/// A recorded exception.
pub(super) const fn err(text: &'static str) -> Result<&'static [&'static str], &'static str> {
    Err(text)
}

const SPLIT_LIMITS: [i32; 5] = [0, -1, 1, 2, 3];
const STRING_SPLIT_LIMITS: [i32; 2] = [0, 2];

#[derive(Default, Debug)]
struct Tally {
    /// Answers the engine gave, all equal to Java's.
    decided: usize,
    /// Answers the engine counted instead.
    counted: usize,
    mismatches: Vec<String>,
    /// Patterns Java compiled, and how many of them the engine compiled.
    java_patterns: usize,
    native_patterns: usize,
    /// Reasons patterns Java accepts were counted, for the report.
    reasons: std::collections::BTreeMap<String, usize>,
}

impl Tally {
    fn compare<T: PartialEq + std::fmt::Debug>(
        &mut self,
        what: impl FnOnce() -> String,
        ours: Result<T, Unsupported>,
        java: T,
    ) {
        match ours {
            Err(_) => self.counted += 1,
            Ok(ours) if ours == java => self.decided += 1,
            Ok(ours) => self
                .mismatches
                .push(format!("{}: native {ours:?}, Java {java:?}", what())),
        }
    }
}

fn exception_text(thrown: &Thrown) -> String {
    format!("!{}: {}", thrown.class.replace('/', "."), thrown.message)
}

fn parts_text(parts: Result<&[&str], &str>) -> Result<Vec<String>, String> {
    parts
        .map(|parts| parts.iter().map(|part| (*part).to_owned()).collect())
        .map_err(str::to_owned)
}

fn check(case: &Case, tally: &mut Tally) {
    let regex = Regex::compile(case.pattern, case.flags);
    let regex = match (regex, case.compile_error) {
        (Ok(_), Some(error)) => {
            tally.mismatches.push(format!(
                "{:?} (flags {}) compiles natively; Java: {error}",
                case.pattern, case.flags
            ));
            return;
        }
        (Err(Unsupported(reason)), error) => {
            tally.counted += 1;
            if error.is_none() {
                tally.java_patterns += 1;
                *tally.reasons.entry(reason).or_default() += 1;
            }
            return;
        }
        (Ok(regex), None) => {
            tally.java_patterns += 1;
            tally.native_patterns += 1;
            regex
        }
    };
    let label = |what: &str, input: &str| {
        format!("{:?} /{}/ {what} on {input:?}", case.pattern, case.flags)
    };
    tally.compare(
        || label("groupCount", ""),
        Ok(regex.group_count()),
        case.groups,
    );
    for item in case.inputs {
        let input = item.input;
        tally.compare(
            || label("matches", input),
            regex.match_start(input, true).map(|m| m.is_some()),
            item.matches,
        );
        tally.compare(
            || label("lookingAt", input),
            regex.match_start(input, false).map(|m| m.is_some()),
            item.looking_at,
        );
        // Every find; a group whose value is not promised is skipped.
        let found = super::units(input).and_then(|chars| regex.find_all(&chars, Some(40)));
        match found {
            Err(_) => tally.counted += 1,
            Ok(found) => {
                if found.len() != item.find.len() {
                    tally.mismatches.push(format!(
                        "{}: native {} matches, Java {}",
                        label("find", input),
                        found.len(),
                        item.find.len()
                    ));
                }
                for (ours, java) in found.iter().zip(item.find) {
                    for group in 0..=regex.group_count() {
                        let java_bounds = (java[2 * group] >= 0)
                            .then(|| (java[2 * group] as usize, java[2 * group + 1] as usize));
                        let ours = ours.group(group);
                        if ours.is_ok() {
                            tally.compare(
                                || label(&format!("find group {group}"), input),
                                ours,
                                java_bounds,
                            );
                        }
                    }
                }
            }
        }
        for (replacement, all, first) in item.replace {
            for (is_all, java) in [(true, all), (false, first)] {
                let ours = regex
                    .replace(input, replacement, is_all)
                    .map(|result| result.unwrap_or_else(|thrown| exception_text(&thrown)));
                tally.compare(
                    || {
                        label(
                            &format!(
                                "replace{} {replacement:?}",
                                if is_all { "All" } else { "First" }
                            ),
                            input,
                        )
                    },
                    ours,
                    (*java).to_owned(),
                );
            }
        }
        for (limit, java) in SPLIT_LIMITS.iter().zip(item.split) {
            tally.compare(
                || label(&format!("split {limit}"), input),
                regex.split(input, *limit).map(Ok),
                parts_text(*java),
            );
        }
        if let Some(java_splits) = item.string_split {
            for (limit, java) in STRING_SPLIT_LIMITS.iter().zip(java_splits.iter()) {
                tally.compare(
                    || label(&format!("String.split {limit}"), input),
                    string_split(input, case.pattern, *limit).map(Ok),
                    parts_text(*java),
                );
            }
        }
    }
}

/// Every recorded case: no answer differs from Java's, no pattern Java
/// rejects compiles, and the engine decides the large majority of calls.
#[test]
fn answers_like_openjdk_27() {
    let mut tally = Tally::default();
    for case in oracle_cases::CASES {
        check(case, &mut tally);
    }
    assert!(
        tally.mismatches.is_empty(),
        "{} mismatches:\n{}",
        tally.mismatches.len(),
        tally.mismatches.join("\n")
    );
    // A floor, so a regression that counts everything cannot pass silently.
    assert!(
        tally.decided > 10 * tally.counted,
        "decided {} counted {}",
        tally.decided,
        tally.counted
    );
}

/// The id and version validators mods run before they register anything
/// (carried over from the earlier whole-input matcher). Expected answers are
/// `"input".matches(pattern)` on OpenJDK 27.
#[test]
fn validators_match_like_java() {
    let cases: &[(&str, &str, bool)] = &[
        ("[a-z0-9_.-]*", "supermartijn642corelib", true),
        ("[a-z0-9_.-]*", "Bad Id", false),
        ("[a-z0-9_.-]*", "", true),
        ("[a-z0-9_.-]+", "", false),
        ("^[a-z][a-z0-9_]{1,63}$", "carryon", true),
        ("^[a-z][a-z0-9_]{1,63}$", "c", false),
        ("\\d+(\\.\\d+)*", "1.21.10", true),
        ("\\d+(\\.\\d+)*", "1.21.", false),
        ("(?:foo|bar)baz", "barbaz", true),
        ("(?:foo|bar)baz", "foobar", false),
        ("a.c", "abc", true),
        ("a.c", "a\nc", false),
        ("[^\\s]+", "no-space", true),
        ("[^\\s]+", "has space", false),
        ("\\w+:\\w+", "minecraft:stone", true),
        ("x*?y", "xxy", true),
        ("(a*)*b", "aaaaaaaaaaac", false),
        ("[a-]", "-", true),
        // Outside the earlier matcher's subset; answered now.
        ("\\bword", "abc", false),
        ("\\p{L}+", "abc", true),
        ("(?i)abc", "abc", true),
        ("a++", "abc", false),
        ("[a-z&&[^q]]", "abc", false),
        ("(a)\\1", "abc", false),
    ];
    for (pattern, input, expected) in cases {
        assert_eq!(
            matches(pattern, input),
            Ok(*expected),
            "{pattern:?} on {input:?}"
        );
    }
}

/// What needs Unicode tables, other flags or the astral planes is counted.
#[test]
fn outside_the_subset_is_counted_not_guessed() {
    for (pattern, input) in [
        ("\\p{IsAlphabetic}", "abc"),
        ("(?x) a b", "ab"),
        ("(?u)a", "a"),
        ("\\p{L}", "\u{e9}"),
        ("a\\b", "a\u{e9}"),
        (".", "\u{1F600}"),
    ] {
        assert!(matches(pattern, input).is_err(), "{pattern:?} on {input:?}");
    }
}

/// The answer a call must give: Java's (from OpenJDK 27), or none at all
/// (counted). A wrong answer fails.
fn java_or_counted<T: PartialEq + std::fmt::Debug>(
    what: &str,
    ours: Result<T, Unsupported>,
    java: T,
) {
    if let Ok(ours) = ours {
        assert_eq!(ours, java, "{what}");
    }
}

/// The independent review of #81 found these answered wrongly: back
/// references to groups whose value Java keeps by `GroupCurly`/zero-width
/// rules, and `&&` operands Java binds differently. Each must now be Java's
/// answer or counted. Expected values from OpenJDK 27.
#[test]
fn review_cases_answer_like_java_or_are_counted() {
    let matches_cases: &[(&str, &str, bool)] = &[
        ("(?:(\\w))*\\1", "ab", true),
        ("[a&&[b]&x]", "a", true),
        ("[a&&[b]&]", "&", true),
        ("[a-z&&[^aeiou]&]", "&", true),
        ("[ab&&[b]&c]", "a", true),
        ("[ab&&[b]&c]", "b", true),
        ("[ab&&[b]&c]", "c", true),
        ("[ab&&[b]&c]", "&", true),
        ("[^a&&[b]&]", "a", false),
        ("[^a&&[b]&]", "&", false),
        ("[^a&&[b]&]", "b", true),
        ("[a&&[a]b&&b]", "a", true),
        ("[a&&[a]-&&\\^]", "a", true),
        ("[\\[&&[[^b-d]\\x61\\^\\W\\W]-&&\\^]", "[", true),
    ];
    for (pattern, input, java) in matches_cases {
        java_or_counted(
            &format!("{pattern:?} matches {input:?}"),
            matches(pattern, input),
            *java,
        );
    }
    let replace_cases: &[(&str, &str, &str, &str)] = &[
        ("(?:(\\w))*\\1", "a", "X", "X"),
        ("(?:(a)b)*\\1", "abb", "X", "Xbb"),
        ("((a)(b))*\\2", "ab", "X", "Xb"),
        ("(?:x(a))*xa\\1", "xaa", "X", "X"),
        ("(?:(\\w)(\\w))*\\1", "aa", "X", "Xa"),
        ("((?=a))*\\1", "a", "<$0>", "a"),
        ("((?=a)){0,2}\\1", "ab", "<$0>", "ab"),
        ("((?=a))*?\\1", "ab", "<$0>", "ab"),
        ("((?<=a))*\\1", "ab", "<$0>", "ab"),
        (
            "b[\\]]|((?!(ab{2,}[^A-Z])\\n(x{2,})+x)(?:)){0,2}(?>(?:\\1)++(?>b|_+\\na))|x",
            "a_ab\n",
            "X",
            "a_ab\n",
        ),
    ];
    for (pattern, input, replacement, java) in replace_cases {
        java_or_counted(
            &format!("{pattern:?} replaceAll {input:?}"),
            super::replace(input, pattern, replacement, true).map(|result| result.ok()),
            Some((*java).to_owned()),
        );
    }
    java_or_counted(
        "[a&&[b]&x] split 1a2",
        string_split("1a2", "[a&&[b]&x]", 0),
        vec!["1".to_owned(), "2".to_owned()],
    );
}

/// Shapes whose recursion grows with the input, and the shortest input
/// length (in characters) on which OpenJDK 27 threw `StackOverflowError`
/// over seven settings: `-Xint`, C1 and tiered (cold and warm), on 1 MB and
/// 512 KB threads (`-Xint` on 512 KB was the lowest for every shape).
/// `None`: Java runs the shape iteratively and never overflowed (tried up
/// to 524,288 characters).
/// (pattern, repeated unit, prefix, suffix, `find` rather than `matches`,
/// Java's shortest overflowing length, Java's answer on 100 characters)
const JAVA_OVERFLOWS: &[(&str, &str, &str, &str, bool, Option<usize>, bool)] = &[
    ("(a|b)*", "ab", "", "", false, Some(535), true),
    ("^(?:\\w|-)+$", "a-", "", "", false, Some(535), true),
    ("(?:\\s|,)+", " ,", "", "", false, Some(535), true),
    ("((?:a|b)c?)*", "abc", "", "", false, Some(530), true),
    ("(?:a|b)*?c", "ab", "", "c", false, Some(535), true),
    ("(?:(?!x).)*", "ab", "", "", false, None, true),
    (
        "\"(?:\\\\.|[^\"\\\\])*\"",
        "a\\\"",
        "\"",
        "\"",
        false,
        Some(737),
        true,
    ),
    ("(\\w+\\s?)*", "ab ", "", "", false, Some(1870), true),
    ("(?:a|b)+$", "ab", "", "", true, Some(535), true),
    ("(?:ab|cd)*", "abcd", "", "", false, Some(1038), true),
    ("(?:a(?=b)|b)*", "ab", "", "", false, Some(490), true),
    ("(?:a|b)*+", "ab", "", "", false, None, true),
    ("(?:a|b)*c", "ab", "", "", true, Some(535), false),
    ("(?:[a-z]|\\d)*", "a1", "", "", false, Some(535), true),
    ("(?:(a)|b)*", "ab", "", "", false, Some(454), true),
    ("(?:ab)*", "ab", "", "", false, None, true),
];

fn overflow_input(unit: &str, prefix: &str, suffix: &str, n: usize) -> Vec<char> {
    let mut text: Vec<char> = prefix.chars().collect();
    text.extend(unit.chars().cycle().take(n));
    text.extend(suffix.chars());
    text
}

/// One search with the given limits: its answer and the deepest recursion
/// and stack it used.
fn probe_depth(
    pattern: &str,
    text: &[char],
    find: bool,
    limits: super::engine::Limits,
) -> (Result<bool, Unsupported>, usize, usize) {
    let regex = Regex::compile(pattern, 0).expect("modelled");
    let mut matcher = super::engine::Matcher::new(&regex.program, text, limits);
    let answer = if find {
        matcher.search(0)
    } else {
        matcher.match_at_start(true)
    };
    let bytes = matcher.stack_base_minus_low();
    (answer, matcher.peak_depth, bytes)
}

/// Prints, for each shape, the node depth this engine reaches on the
/// shortest input Java overflowed on and the stack bytes per node of this
/// build. `MAX_DEPTH` is chosen from this table.
#[test]
#[ignore = "a measurement, run with --nocapture"]
fn measure_depth_against_java_overflows() {
    std::thread::Builder::new()
        .stack_size(1 << 30)
        .spawn(|| {
            let free = super::engine::Limits {
                depth: usize::MAX,
                stack: usize::MAX,
            };
            for (pattern, unit, prefix, suffix, find, java, _) in JAVA_OVERFLOWS {
                let n = java.unwrap_or(2_000);
                let text = overflow_input(unit, prefix, suffix, n);
                let (answer, depth, bytes) = probe_depth(pattern, &text, *find, free);
                println!(
                    "{pattern:24} java_n={java:?} depth={depth} per_char={:.2} bytes_per_node={} answer={answer:?}",
                    depth as f64 / n as f64,
                    bytes / depth.max(1),
                );
            }
        })
        .unwrap()
        .join()
        .unwrap();
}

/// Every deep shape on a 2 MB thread (a test harness's default) in any
/// build, with no thread of its own: answered like JDK 27 on 100 characters,
/// counted from the shortest input JDK 27 overflowed on, and never more
/// than a counted answer on 200,000 characters. The bound sits at least
/// twice below the depth those Java overflows correspond to.
#[test]
fn deep_searches_are_counted_where_java_can_overflow() {
    use super::engine::{Limits, MAX_DEPTH};
    std::thread::Builder::new()
        .stack_size(2 << 20)
        .spawn(|| {
            for (pattern, unit, prefix, suffix, find, java, short) in JAVA_OVERFLOWS {
                let text = overflow_input(unit, prefix, suffix, 100);
                let (answer, _, _) = probe_depth(pattern, &text, *find, Limits::JAVA);
                assert_eq!(answer, Ok(*short), "{pattern} on 100 characters");
                if let Some(n) = java {
                    let text = overflow_input(unit, prefix, suffix, *n);
                    let (answer, _, _) = probe_depth(pattern, &text, *find, Limits::JAVA);
                    assert!(
                        answer.is_err(),
                        "{pattern} answered at Java's overflow ({n})"
                    );
                }
                let text = overflow_input(unit, prefix, suffix, 200_000);
                let _ = probe_depth(pattern, &text, *find, Limits::JAVA);
            }
        })
        .unwrap()
        .join()
        .unwrap();
    // The margin, measured without limits on a large stack.
    std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(|| {
            let free = Limits {
                depth: usize::MAX,
                stack: usize::MAX,
            };
            for (pattern, unit, prefix, suffix, find, java, _) in JAVA_OVERFLOWS {
                let Some(n) = java else { continue };
                let text = overflow_input(unit, prefix, suffix, *n);
                let (_, depth, _) = probe_depth(pattern, &text, *find, free);
                assert!(
                    depth >= 2 * MAX_DEPTH,
                    "{pattern}: Java overflowed at depth {depth}"
                );
            }
        })
        .unwrap()
        .join()
        .unwrap();
}

/// The second independent review of #81: `\R` in a repeated group (Java's
/// `GroupCurly` makes each iteration atomic), `\v` as a range endpoint
/// (U+000B), and `\c` whose operand is `\` (`\Q` opens a quote first).
/// (pattern, input, call, replacement, OpenJDK 27's answer: `OK <value>`,
/// with split parts joined by `|`, or `PSE` for a rejected pattern). Each
/// must be Java's answer or counted; the shapes now modelled must answer.
#[test]
fn second_review_cases_answer_like_java_or_are_counted() {
    let cases: &[(&str, &str, &str, &str, &str)] = &[
        (
            "(\\R){2,}",
            "line1\u{d}\u{a}line2",
            "replaceAll",
            "\u{a}\u{a}",
            "OK line1\u{d}\u{a}line2",
        ),
        (
            "(?:\\R){2,}",
            "a\u{d}\u{a}b",
            "split",
            "",
            "OK a\u{d}\u{a}b",
        ),
        ("(?:\\R){2}", "\u{d}\u{a}", "matches", "", "OK false"),
        ("(?:\\R){1}\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        (
            "(?:\\R)*\\n",
            "\u{d}\u{a}",
            "replaceAll",
            "<$0>",
            "OK \u{d}<\u{a}>",
        ),
        (
            "(?:x\\R)*\\n",
            "x\u{d}\u{a}x\u{d}\u{a}",
            "replaceAll",
            "<$0>",
            "OK x\u{d}<\u{a}>x\u{d}<\u{a}>",
        ),
        (
            "(\\R){0,2}\\1",
            "\u{d}\u{a}\u{a}aba",
            "replaceAll",
            "<$0>",
            "OK \u{d}<\u{a}\u{a}>aba",
        ),
        ("(?:\\R)*\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        ("(\\R)*\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        ("(\\R)+\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        (
            "(?:\\R){2}\\n",
            "\u{d}\u{d}\u{a}",
            "matches",
            "",
            "OK false",
        ),
        ("(?:\\R)*?\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        ("(?:\\R){1,3}\\n", "\u{d}\u{a}", "matches", "", "OK false"),
        (
            "(?:x\\R)*\\n",
            "x\u{d}\u{a}x\u{d}\u{a}",
            "matches",
            "",
            "OK false",
        ),
        ("(\\R){2}", "\u{d}\u{a}", "matches", "", "OK false"),
        (
            "((?:\\R){2})\\n",
            "\u{d}\u{d}\u{a}",
            "matches",
            "",
            "OK false",
        ),
        (
            "(?:\\R\\R)*\\n",
            "\u{d}\u{d}\u{a}",
            "matches",
            "",
            "OK false",
        ),
        (
            "b(?:(?:\\R){2}){1}([ab]a)+",
            "b\u{d}\u{a}babx",
            "replaceAll",
            "<$0>",
            "OK b\u{d}\u{a}babx",
        ),
        ("(?:\\R)?\\n", "\u{d}\u{a}", "matches", "", "OK true"),
        ("(\\R)??\\n", "\u{d}\u{a}", "matches", "", "OK true"),
        ("\\R\\n", "\u{d}\u{a}", "matches", "", "OK true"),
        ("[\\v-z]", "a-b", "replaceAll", "X", "OK XXX"),
        ("[\\v-\\W]", "a", "matches", "", "PSE"),
        ("[\\v-z]", "a", "matches", "", "OK true"),
        ("[\\v-]", "\u{a}", "matches", "", "OK false"),
        ("[\\v-]", "-", "matches", "", "OK true"),
        ("[\\v-]", "\u{b}", "matches", "", "OK true"),
        ("[^\\v-z]", "a", "matches", "", "OK false"),
        ("[\\v-\\v]", "-", "matches", "", "OK false"),
        ("[\\v-\\v]", "\u{b}", "matches", "", "OK true"),
        ("[\\t-\\v]", "\u{a}", "matches", "", "OK true"),
        ("[\\v-\\r]", "-", "matches", "", "OK false"),
        ("[\\v-\\r]", "\u{c}", "matches", "", "OK true"),
        ("[\\v-A-Z]", "B", "matches", "", "OK false"),
        ("[\\v-\\-]", "&", "matches", "", "OK true"),
        ("[\\v-\\x41]", "&", "matches", "", "OK true"),
        ("[\\v-\\u0045]", "A", "matches", "", "OK true"),
        ("[\\v-a-]", "A", "matches", "", "OK true"),
        ("[\\v-b-d]", "a", "matches", "", "OK true"),
        ("[\\v-z\\v]", "a", "matches", "", "OK true"),
        ("[\\v-\u{e9}]", "a", "matches", "", "OK true"),
        ("[\\v-\\d]", "a", "matches", "", "PSE"),
        ("[\\v-\\c[]", "-", "matches", "", "OK false"),
        ("[\\v-\\e]", "-", "matches", "", "OK false"),
        ("[\\v-\\f]", "-", "matches", "", "OK false"),
        ("[^\\v-]", "\u{a}", "matches", "", "OK true"),
        ("[a\\v]", "\u{a}", "matches", "", "OK true"),
        ("[\\v]", "\u{b}", "matches", "", "OK true"),
        (
            "\\pN{0,2}[b-c\\v-\\\\]",
            "9N0&",
            "replaceAll",
            "<$0>",
            "OK <9N><0&>",
        ),
        ("\\c\\Q.", "\u{1c}Q.", "matches", "", "OK false"),
        ("\\c\\Qab", "!b", "matches", "", "OK true"),
        (
            "a\\c\\Q*",
            "\u{1c}Qab",
            "replaceAll",
            "<$0>",
            "OK \u{1c}Q<a>b",
        ),
        ("[\\c\\Q]", "Q7", "replaceAll", "<$0>", "OK Q7"),
        ("\\c\\\\", "\u{1c}\\", "matches", "", "PSE"),
    ];
    let answered = [
        "[\\v-z]",
        "[\\v-]",
        "[^\\v-z]",
        "[\\v-\\v]",
        "[\\t-\\v]",
        "[\\v-\\r]",
        "[\\v-A-Z]",
        "[\\v-\\x41]",
        "(?:\\R)?\\n",
        "(\\R)??\\n",
        "\\R\\n",
    ];
    for (pattern, input, call, replacement, java) in cases {
        let ours = match *call {
            "matches" => matches(pattern, input).map(|m| m.to_string()),
            "replaceAll" => super::replace(input, pattern, replacement, true)
                .map(|result| result.unwrap_or_else(|thrown| format!("{thrown:?}"))),
            _ => string_split(input, pattern, 0).map(|parts| parts.join("|")),
        };
        match (java.strip_prefix("OK "), ours) {
            (Some(java), Ok(ours)) => assert_eq!(ours, java, "{pattern:?} {call} {input:?}"),
            (None, Ok(ours)) => panic!("{pattern:?}: Java {java}, answered {ours:?}"),
            (_, Err(_)) => assert!(
                !answered.contains(pattern),
                "{pattern:?} {call} {input:?} is modelled but was counted"
            ),
        }
    }
}

/// `Pattern.quote` and `Matcher.quoteReplacement`, answers from OpenJDK 27.
#[test]
fn quoting_matches_the_jdk() {
    assert_eq!(quote("a.b"), "\\Qa.b\\E");
    assert_eq!(quote("x\\Ey"), "\\Qx\\E\\\\E\\Qy\\E");
    assert_eq!(quote("\\E"), "\\Q\\E\\\\E\\Q\\E");
    assert_eq!(quote_replacement("a$b\\c"), "a\\$b\\\\c");
    assert_eq!(quote_replacement("plain"), "plain");
}

/// Diff the engine against any answer file from `java_regex_oracle.py`
/// (`HORIZON_REGEX_ORACLE=answers.json cargo test -- --ignored oracle_file`).
#[test]
#[ignore = "needs an oracle answer file"]
fn oracle_file() {
    let Some(path) = std::env::var_os("HORIZON_REGEX_ORACLE") else {
        return;
    };
    let text = std::fs::read_to_string(path).unwrap();
    let answers: serde_json::Value = serde_json::from_str(&text).unwrap();
    let leak = |value: &serde_json::Value| -> &'static str {
        Box::leak(
            value
                .as_str()
                .unwrap_or_default()
                .to_owned()
                .into_boxed_str(),
        )
    };
    let parts = |value: &serde_json::Value| -> Result<&'static [&'static str], &'static str> {
        match value.as_array() {
            Some(items) => Ok(Box::leak(
                items
                    .iter()
                    .map(leak)
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
            )),
            None => Err(leak(value)),
        }
    };
    let mut tally = Tally::default();
    for case in answers.as_array().unwrap() {
        let inputs: Vec<Input> = case["inputs"]
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter(|item| item.get("error").is_none())
                    .map(|item| Input {
                        input: leak(&item["input"]),
                        matches: item["matches"].as_bool().unwrap(),
                        looking_at: item["lookingAt"].as_bool().unwrap(),
                        find: Box::leak(
                            item["find"]
                                .as_array()
                                .unwrap()
                                .iter()
                                .map(|found| -> &'static [i64] {
                                    Box::leak(
                                        found
                                            .as_array()
                                            .unwrap()
                                            .iter()
                                            .map(|v| v.as_i64().unwrap())
                                            .collect::<Vec<_>>()
                                            .into_boxed_slice(),
                                    )
                                })
                                .collect::<Vec<_>>()
                                .into_boxed_slice(),
                        ),
                        replace: Box::leak(
                            item["replace"]
                                .as_array()
                                .unwrap()
                                .iter()
                                .map(|triple| {
                                    (leak(&triple[0]), leak(&triple[1]), leak(&triple[2]))
                                })
                                .collect::<Vec<_>>()
                                .into_boxed_slice(),
                        ),
                        split: Box::leak(
                            item["split"]
                                .as_array()
                                .unwrap()
                                .iter()
                                .map(parts)
                                .collect::<Vec<_>>()
                                .into_boxed_slice(),
                        ),
                        string_split: item.get("stringSplit").map(|splits| -> &'static [_] {
                            Box::leak(
                                splits
                                    .as_array()
                                    .unwrap()
                                    .iter()
                                    .map(parts)
                                    .collect::<Vec<_>>()
                                    .into_boxed_slice(),
                            )
                        }),
                    })
                    .collect()
            })
            .unwrap_or_default();
        let case = Case {
            pattern: leak(&case["pattern"]),
            flags: case["flags"].as_i64().unwrap() as i32,
            compile_error: case.get("compile").map(leak),
            groups: case["groups"].as_u64().unwrap_or(0) as usize,
            inputs: Box::leak(inputs.into_boxed_slice()),
        };
        check(&case, &mut tally);
    }
    eprintln!(
        "decided {} counted {} mismatches {}; patterns: Java {} native {}",
        tally.decided,
        tally.counted,
        tally.mismatches.len(),
        tally.java_patterns,
        tally.native_patterns,
    );
    let mut reasons: Vec<_> = tally.reasons.iter().collect();
    reasons.sort_by_key(|(_, count)| std::cmp::Reverse(**count));
    for (reason, count) in reasons.iter().take(25) {
        eprintln!("  {count:5} {reason}");
    }
    for mismatch in tally.mismatches.iter().take(60) {
        eprintln!("{mismatch}");
    }
    assert!(tally.mismatches.is_empty());
}
